//! The Pi adapter: render and unregister a small TypeScript input hook.

const std = @import("std");
const settings = @import("settings.zig");

const Io = std.Io;
const Allocator = std.mem.Allocator;

pub const shim_name = "extensions/enforcer.ts";
pub const shim_header = "// generated by `enforcer on`; run `enforcer off` to remove";

pub fn renderShim(gpa: Allocator, self_path: []const u8) ![]u8 {
    // A JSON string literal is a valid TypeScript string literal. This keeps a
    // path containing quotes or backslashes from breaking the generated file.
    const quoted = try std.json.Stringify.valueAlloc(gpa, self_path, .{});
    defer gpa.free(quoted);

    return std.fmt.allocPrint(
        gpa,
        "{s}\n" ++
            "import {{ spawnSync }} from \"node:child_process\";\n" ++
            "import type {{ ExtensionAPI }} from \"@earendil-works/pi-coding-agent\";\n\n" ++
            "const ENFORCER = {s};\n\n" ++
            "export default function (pi: ExtensionAPI) {{\n" ++
            "  pi.on(\"input\", (event, ctx) => {{\n" ++
            "    const r = spawnSync(ENFORCER, [\"hook\"], {{\n" ++
            "      input: JSON.stringify({{ prompt: event.text }}),\n" ++
            "      encoding: \"utf8\",\n" ++
            "      timeout: 5000,\n" ++
            "    }});\n" ++
            "    if (r.status === 2) {{\n" ++
            "      ctx.ui.notify((r.stderr || \"blocked by enforcer\").trim(), \"warning\");\n" ++
            "      return {{ action: \"handled\" }};\n" ++
            "    }}\n" ++
            "    return {{ action: \"continue\" }};\n" ++
            "  }});\n" ++
            "}}\n",
        .{ shim_header, quoted },
    );
}

pub fn install(io: Io, gpa: Allocator, agent_dir: Io.Dir, self_path: []const u8) !settings.Outcome {
    const shim = try renderShim(gpa, self_path);
    defer gpa.free(shim);

    const stat = agent_dir.statFile(io, "extensions", .{ .follow_symlinks = false }) catch |err| switch (err) {
        error.FileNotFound => null,
        else => return err,
    };
    if (stat) |s| switch (s.kind) {
        .sym_link => return error.SettingsIsSymlink,
        .directory => {},
        else => return error.SettingsNotRegularFile,
    } else {
        try agent_dir.createDirPath(io, "extensions");
    }

    return settings.updateFile(io, gpa, agent_dir, shim_name, shim);
}

pub fn uninstall(io: Io, gpa: Allocator, agent_dir: Io.Dir) !settings.Outcome {
    return settings.removeFile(io, gpa, agent_dir, shim_name, shim_header);
}

test "renderShim embeds an absolute path and the hook contract" {
    const gpa = std.testing.allocator;
    const shim = try renderShim(gpa, "/usr/local/bin/enforcer");
    defer gpa.free(shim);

    try std.testing.expect(std.mem.startsWith(u8, shim, shim_header ++ "\n"));
    try std.testing.expect(std.mem.indexOf(u8, shim, "const ENFORCER = \"/usr/local/bin/enforcer\";") != null);
    try std.testing.expect(std.mem.indexOf(u8, shim, "spawnSync") != null);
    try std.testing.expect(std.mem.indexOf(u8, shim, "return { action: \"handled\" };") != null);
}

test "install and uninstall are idempotent" {
    const io = std.testing.io;
    const gpa = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    try std.testing.expectEqual(settings.Outcome.changed, try install(io, gpa, tmp.dir, "/bin/enforcer"));
    try std.testing.expectEqual(settings.Outcome.unchanged, try install(io, gpa, tmp.dir, "/bin/enforcer"));
    try std.testing.expectEqual(settings.Outcome.changed, try uninstall(io, gpa, tmp.dir));
    try std.testing.expectEqual(settings.Outcome.unchanged, try uninstall(io, gpa, tmp.dir));
}

test "uninstall leaves a hand-written extension alone" {
    const io = std.testing.io;
    const gpa = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    try tmp.dir.createDirPath(io, "extensions");
    const original = "// my extension\nexport default function () {}\n";
    try settings.updateFile(io, gpa, tmp.dir, shim_name, original);
    try std.testing.expectError(error.NotOurFile, uninstall(io, gpa, tmp.dir));
}

test "install refuses a symlinked extensions directory" {
    if (@import("builtin").os.tag == .windows) return error.SkipZigTest;
    const io = std.testing.io;
    const gpa = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    try tmp.dir.createDirPath(io, "real");
    try tmp.dir.symLink(io, "real", "extensions", .{ .is_directory = true });
    try std.testing.expectError(error.SettingsIsSymlink, install(io, gpa, tmp.dir, "/bin/enforcer"));
}
